-- Create "agent_settings" table
CREATE TABLE "agent"."agent_settings" ("id" bigint NOT NULL GENERATED BY DEFAULT AS IDENTITY, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, "financial_enabled" boolean NOT NULL DEFAULT false, "workspace_id" bigint NOT NULL, "created_by" bigint NOT NULL, "updated_by" bigint NOT NULL, "financial_provider_id" bigint NULL, PRIMARY KEY ("id"), CONSTRAINT "agent_settings_agent_providers_financial_provider" FOREIGN KEY ("financial_provider_id") REFERENCES "agent"."agent_providers" ("id") ON UPDATE NO ACTION ON DELETE SET NULL, CONSTRAINT "agent_settings_users_creator" FOREIGN KEY ("created_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_settings_users_updater" FOREIGN KEY ("updated_by") REFERENCES "core"."users" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION, CONSTRAINT "agent_settings_workspaces_workspace" FOREIGN KEY ("workspace_id") REFERENCES "core"."workspaces" ("id") ON UPDATE NO ACTION ON DELETE NO ACTION);
-- Create index "agentsetting_workspace_id" to table: "agent_settings"
CREATE UNIQUE INDEX "agentsetting_workspace_id" ON "agent"."agent_settings" ("workspace_id");
